const InputMessage = forwardRef<HTMLDivElement, InputMessageProps>(({ value, onValueChange, onSend, placeholder = "Ask me anything…", leftSlot, rightSlot, voiceInput, header, footer, disclaimer, composerClassName, footerClassName, disabled, minRows = 1, maxRows = 8, clickToFocus = true, sendLabel = "Send", sendVariant = "neutral", layout = "expanded", files, onFilesChange, accept = DEFAULT_ACCEPT, maxFiles, filePreviewSize = 80, textareaProps, textareaRef: externalTextareaRef, autoDispatchQueue = true, status, onStop, queue, onQueueChange, showQueue = true, history = [], className, style, ...props }, ref) => {
